  <script>
    // reveal on scroll
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const revealEls = Array.from(document.querySelectorAll('.reveal'));
      if(prefersReduced){ revealEls.forEach(el=>el.classList.add('visible')); return; }
      const onScroll = ()=>{
        const viewH = window.innerHeight || document.documentElement.clientHeight;
        revealEls.forEach(el=>{
          if(el.classList.contains('visible')) return;
          const r = el.getBoundingClientRect();
          if(r.top <= viewH - 80) el.classList.add('visible');
        });
      };
      onScroll();
      window.addEventListener('scroll', onScroll, {passive:true});
    })();

    // simple date selector
    (function(){
      const datesEl = document.getElementById('dates');
      const today = new Date();
      const options = [];
      for(let i=3;i<20;i+=3){ const d = new Date(); d.setDate(today.getDate()+i); options.push(d); }
      options.forEach(d=>{
        const el = document.createElement('div');
        el.className='date';
        el.tabIndex=0;
        el.textContent = d.toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'});
        el.dataset.iso = d.toISOString();
        el.addEventListener('click', ()=>{ document.querySelectorAll('.date').forEach(x=>x.classList.remove('selected')); el.classList.add('selected'); });
        datesEl.appendChild(el);
      });
    })();

    // booking form submit (mock)
    document.getElementById('bookingForm').addEventListener('submit', function(e){
      e.preventDefault();
      const name = this.name.value.trim(); const email = this.email.value.trim(); const plan = this.plan.value;
      const selected = document.querySelector('.date.selected');
      if(!selected){ alert('Pick a preferred date.'); return; }
      const dateIso = selected.dataset.iso;
      // fake send
      alert('Thanks, '+name+'! We received your request for '+plan+'. A confirmation will be sent to '+email+'.');
      this.reset(); document.querySelectorAll('.date').forEach(x=>x.classList.remove('selected'));
    });

    // Modal quick exercise (90s) — breathing + micro-clarity
    (function(){
      const backdrop = document.getElementById('modalBackdrop');
      const start = document.getElementById('modalStart');
      const close = document.getElementById('modalClose');
      const output = document.getElementById('modalOutput');
      const quickBtn = document.getElementById('quickExercise');
      quickBtn.addEventListener('click', ()=>{ backdrop.style.display='flex'; backdrop.setAttribute('aria-hidden','false'); });
      close.addEventListener('click', ()=>{ backdrop.style.display='none'; backdrop.setAttribute('aria-hidden','true'); stop(); });

      let timer=null; let step=0; const steps = [ {text:'Breathe in (4s)',dur:4000},{text:'Hold (2s)',dur:2000},{text:'Breathe out (6s)',dur:6000}, {text:'Name one tiny next action',dur:80000} ];
      function stop(){ if(timer){ clearTimeout(timer); timer=null; } }
      start.addEventListener('click', ()=>{
        step=0; output.textContent=''; runStep();
      });
      function runStep(){ if(step>=steps.length){ output.textContent='Done — thank you.'; return; }
        const s = steps[step]; output.textContent = s.text;
        timer = setTimeout(()=>{ step++; runStep(); }, s.dur);
      }
    })();
  </script>
